/**
 * @name Taint flow to dynamic code execution
 * @description Tracks flow from user-controlled input to dynamic code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/taint-to-code-execution
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CodeExecutionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    // CLI arguments
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source = call
    ) or
    // sys.argv
    exists(DataFlow::AttrRead attr |
      attr.getObject().asExpr().(Name).getId() = "sys" and
      attr.getAttributeName() = "argv" and
      source.asExpr() = attr.asExpr()
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().asExpr().(Name).getId() in ["compile", "getattr", "exec", "eval"] and
      sink = call.getArg(_)
    )
  }
}

module CodeExecutionFlow = TaintTracking::Global<CodeExecutionConfig>;
import CodeExecutionFlow::PathGraph

from CodeExecutionFlow::PathNode source, CodeExecutionFlow::PathNode sink
where CodeExecutionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic code execution with data from $@.", source.getNode(), "user input"

/**
 * @name Unsafe getattr with user-controlled attribute name
 * @description Using getattr with user-controlled attribute names can lead to unauthorized access
 * @kind path-problem
 * @problem.severity warning
 * @id py/unsafe-getattr
 * @tags security
 *        external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module GetattrConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("getattr").getACall() and
      sink = call.getArg(1)
    )
  }
}

module GetattrFlow = TaintTracking::Global<GetattrConfig>;
import GetattrFlow::PathGraph

from GetattrFlow::PathNode source, GetattrFlow::PathNode sink
where GetattrFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe getattr with attribute name from $@.", source.getNode(), "user input"

/**
 * @name Command injection
 * @description Executing system commands with user-controlled input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

